function normalizeType(t) {
  const s = String(t || '').toLowerCase().trim();
  if (s === 'behavioral') return 'behavioral';
  if (s === 'situational' || s === 'gap_probe') return 'situational';
  if (s === 'cultural') return 'cultural';
  return 'technical';
}

function cleanPlaceholders(text) {
  if (!text) return '';
  return String(text)
    .replace(/\[specific project\/system\]/gi, 'your primary project')
    .replace(/\[specific project or technology\]/gi, 'your core technical stack')
    .replace(/\[specific project\]/gi, 'your recent production systems')
    .replace(/\[specific tool\/framework[^\]]*\]/gi, 'PostgreSQL or Docker')
    .replace(/\[specific tool[^\]]*\]/gi, 'your core engineering tools')
    .replace(/\[missing technology[^\]]*\]/gi, 'modern distributed architectures')
    .replace(/\[(?:project|system)[^\]]*\]/gi, 'your recent project')
    .replace(/\[[^\]]+\]/g, '')
    .replace(/\s{2,}/g, ' ')
    .replace(/\s+([,?.!])/g, '$1')
    .trim();
}

