const body = isWebhook
  ? ($("Webhook - /create-session").first().json.body || {})
  : ($("When Executed by Another Workflow").first().json || {});

const campaignId  = body.campaign_id  || body.campaignId  || '';
const candidateId = body.candidate_id || body.candidateId || '';

let jdText = body.jd_text || body.jdText || '';
